import{_ as a,o as i,c as e,a4 as t}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"SSH 服务配置","description":"","frontmatter":{"title":"SSH 服务配置","date":"2026-07-25T00:00:00.000Z"},"headers":[],"relativePath":"posts/03_ssh_setup.md","filePath":"posts/03_ssh_setup.md"}'),h={name:"posts/03_ssh_setup.md"};function n(p,s,l,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="ssh-服务配置" tabindex="-1">SSH 服务配置 <a class="header-anchor" href="#ssh-服务配置" aria-label="Permalink to &quot;SSH 服务配置&quot;">​</a></h1><h2 id="dropbear" tabindex="-1">Dropbear <a class="header-anchor" href="#dropbear" aria-label="Permalink to &quot;Dropbear&quot;">​</a></h2><p>系统自带 dropbear v0.52（2012年版本），路径 <code>/system/xbin/dropbear</code>。</p><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 生成主机密钥</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">mkdir</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -p</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /data/ssh</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">dropbearkey</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -t</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> rsa</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -f</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /data/ssh/dropbear_rsa_host_key</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 启动（端口22）</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">dropbear</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -p</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 22</span></span></code></pre></div><h2 id="踩坑-ssh-端口默认22" tabindex="-1">踩坑：SSH 端口默认22 <a class="header-anchor" href="#踩坑-ssh-端口默认22" aria-label="Permalink to &quot;踩坑：SSH 端口默认22&quot;">​</a></h2><p>用户要求用22端口，不是2222。dropbear 默认就是22，直接 <code>dropbear -p 22</code> 即可。</p><h2 id="踩坑-旧版加密算法" tabindex="-1">踩坑：旧版加密算法 <a class="header-anchor" href="#踩坑-旧版加密算法" aria-label="Permalink to &quot;踩坑：旧版加密算法&quot;">​</a></h2><p>Dropbear v0.52 只支持旧版密钥交换算法 <code>diffie-hellman-group1-sha1</code>，新版 OpenSSH 默认禁用。</p><p>客户端连接需要加参数：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">ssh</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -oKexAlgorithms=+diffie-hellman-group1-sha1</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -oHostKeyAlgorithms=+ssh-rsa</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> root@192.168.31.208</span></span></code></pre></div><p>或者写入 <code>~/.ssh/config</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Host 192.168.31.208</span></span>
<span class="line"><span>    KexAlgorithms +diffie-hellman-group1-sha1</span></span>
<span class="line"><span>    HostKeyAlgorithms +ssh-rsa</span></span>
<span class="line"><span>    PubkeyAcceptedKeyTypes +ssh-rsa</span></span></code></pre></div><h2 id="root-密码" tabindex="-1">Root 密码 <a class="header-anchor" href="#root-密码" aria-label="Permalink to &quot;Root 密码&quot;">​</a></h2><p>默认密码 hash 存在 <code>/etc/passwd</code>。用 <code>openssl passwd -1</code> 生成新密码 hash，通过 system 分区 bind mount 写入。</p>`,15)])])}const g=a(h,[["render",n]]);export{c as __pageData,g as default};
